SET statement_timeout = 0;
CREATE TYPE "public"."order_status" AS ENUM ('open', 'paid');
CREATE TABLE IF NOT EXISTS "public"."orders" (
    "id" bigint NOT NULL,
    "user_id" "uuid" DEFAULT "auth"."uid"() NOT NULL,
    "note" "text",
    "status" "public"."order_status" DEFAULT 'open'::"public"."order_status" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"()
);
ALTER TABLE "public"."orders" OWNER TO "postgres";
ALTER TABLE "public"."orders" ALTER COLUMN "id" ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME "public"."orders_id_seq"
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);
CREATE OR REPLACE VIEW "public"."orders_feed" WITH ("security_invoker"='on') AS
 SELECT "orders"."id", "orders"."note" FROM "public"."orders";
ALTER TABLE ONLY "public"."orders"
    ADD CONSTRAINT "orders_pkey" PRIMARY KEY ("id");
ALTER TABLE ONLY "public"."orders"
    ADD CONSTRAINT "orders_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "auth"."users"("id") ON DELETE CASCADE;
CREATE POLICY "own" ON "public"."orders" USING (("auth"."uid"() = "user_id"));
